def transform(grid):
    """Compare the two separated pattern panels and mark the longer panel's right-tail in the shorter one."""
    from collections import Counter

    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    panels = []
    for r, row in enumerate(grid):
        if any(v != background for v in row):
            if not panels or r != panels[-1][-1] + 1:
                panels.append([])
            panels[-1].append(r)
    if len(panels) < 2:
        return out

    first, second = panels[0], panels[1]
    if len(first) != len(second):
        return out
    edges = [max(c for r in panel for c, v in enumerate(grid[r]) if v != background)
             for panel in (first, second)]
    if edges[0] == edges[1]:
        return out
    short, wide = (first, second) if edges[0] < edges[1] else (second, first)
    short_edge, wide_edge = min(edges), max(edges)
    for rs, rw in zip(short, wide):
        for c in range(short_edge + 1, wide_edge + 1):
            if grid[rs][c] == background and grid[rw][c] != background:
                out[rs][c] = 1
    return out

